{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title explicitly includes the phrase 'systematic review', identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title specifies the population ('children') and the exposure/intervention/outcome focus ('Post-ERCP adverse events' and 'postERCP pancreatitis incidence'), providing key information about the review question."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title indicates the analysis method by including 'meta-analysis', which is relevant supplementary information about the review approach."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background Endoscopic retrograde cholangiopancreatography (ERCP) is increasingly used in children with pancreatobiliary disease, but pediatric adverse-event estimates remain variable.",
      "reason": "The manuscript explicitly describes the current state of knowledge and uncertainty by noting increased use of ERCP in children and that pediatric adverse-event estimates are variable, indicating important uncertainty in the literature."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "We updated the evidence on post-ERCP adverse events in children, pooled post-ERCP pancreatitis (PEP) incidence when study-level data allowed, and summarized reported risk factors and prevention strategies.",
      "reason": "The abstract states the aims to update evidence, provide a pooled incidence estimate, and summarize risk factors and prevention strategies, which explains the importance and need for conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Prior systematic reviews and meta-analyses were used for background comparison and reference checking only.",
      "reason": "The manuscript acknowledges prior systematic reviews and meta-analyses and explains their role (background comparison/reference checking) and that they were not combined with overlapping primary studies, thereby explaining the need and relationship to existing reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses incidence, risk factors, and prevention strategies for adverse events rather than assessing intervention effects; therefore describing an intervention mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a complex intervention or delivery context requiring a logic model; it focuses on adverse-event incidence, risk factors, and prevention strategies, so a logic model is not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": "text_5",
      "quote": null,
      "reason": "No explicit statement of the review objectives or specific review questions is present in the retrieved evidence. The provided chunks include methods, data extraction, and other sections, but none contain a verbatim objective or question framed for the review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "For each primary study, we collected first author, year, country, study design, sample size, number of ERCP procedures, mean or median age, ERCP indications, procedure type, follow-up duration, adverse-event definitions or reporting windows, event numerators and denominators for PEP, bleeding, perforation, cholangitis or infection, severity classification, risk factors, and management strategies.",
      "reason": "The review focuses on adverse-event incidence, risk factors, and prevention strategies (data extraction centers on event numerators/denominators, risk factors, and management) rather than planned intervention-effect comparisons; therefore the PICO-style planned comparisons requirement for intervention-effect reviews does not apply."
    }
  ],
  "confidence": 60
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Inclusion Criteria: Study Type: Original pediatric studies, including cohort studies, case-control studies, and randomized or nonrandomized interventional studies. Prior systematic reviews and meta-analyses were screened for contextual comparison and citation tracking only. Their pooled results were not entered into the present quantitative synthesis. Population: Pediatric patients (<18 years) undergoing ERCP. Outcomes: Reported incidence, types, risk factors, or management strategies of post-ERCP complications.",
      "reason": "The manuscript specifies study designs, the target population (<18 years), and eligible outcomes; data extraction methods (including follow-up duration) are further detailed in text_7, showing study characteristics used to determine eligibility were prespecified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Language: English. Publication Date: January 1, 2015 to June 26, 2025.",
      "reason": "The review explicitly states report-level eligibility restrictions for language and publication date range; other report-status exclusions (e.g., conference abstracts) are listed in the exclusion criteria in the same chunk."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit distinction is reported between excluding studies because outcomes were not measured versus excluding studies because outcome results were not reported; the methods only note exclusion for \"Incomplete or unextractable data\" without separating these reasons."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We prespecified subgroup exploration by age group, ERCP indication, procedure type, pancreatic duct manipulation or contrast injection, sphincterotomy, and operator or center volume. Formal subgroup meta-analysis was not forced when studies did not provide stratified PEP event counts... In response to peer review, we also added a post hoc denominator-unit sensitivity summary, separating procedure-level studies from patient-level or first-ERCP-per-child studies and retaining a mixed/unclear category when the source did not permit classification.",
      "reason": "The review defines groups used in syntheses (prespecified subgroups and a post hoc separation by denominator unit) and links these groupings to how pooled analyses and sensitivity checks were conducted."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The search was limited to studies published between January 1, 2015, and June 26, 2025, to capture contemporary pediatric ERCP practice, including changes in therapeutic indications, endoscopic accessories, anesthesia support, and prophylaxis strategies.",
      "reason": "A rationale is provided for the notable temporal restriction (to capture contemporary practice and related changes), explaining the reason for this eligibility limitation."
    }
  ],
  "confidence": 85
}

