    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": null,
      "reason": "Although follow-up duration and 'reporting windows' were collected, the manuscript does not specify the time frame of measurement for each outcome domain (no explicit per-outcome measurement timeframes are given)."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": null,
      "reason": "The manuscript does not state whether all results compatible with each outcome domain (e.g., all measures, time points, analyses) were sought; there is no explicit statement that all compatible results were collected."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "For PEP, we recorded whether the denominator represented ERCP procedures, patients, first ERCP per child, or a mixed/unclear reporting unit. We retained the denominator unit used by the source rather than converting procedure-level data to patient-level data when repeat procedures per child were not consistently reported.",
      "reason": "When not all compatible result types (different denominator/reporting units) could be harmonized, the manuscript describes the process used to select/retain results (kept source denominator units and did not convert), and sensitivity summary methods are described in text_9."
    },
    {
